WITH base AS (SELECT id, customer_id, plan, start_date, end_date, monthly_fee, status, CASE WHEN monthly_fee >= 248 THEN 'High' WHEN monthly_fee >= 72 THEN 'Medium' ELSE 'Low' END AS monthly_fee_band, DATE_FORMAT(start_date, 'yyyy-MM-dd') AS start_date_label FROM subscriptions WHERE end_date >= DATE '2023-10-02' AND status <> 'EXPIRED'), remaining_keys AS (SELECT plan FROM base EXCEPT ALL SELECT plan FROM subscriptions WHERE MONTH(end_date) IN (2, 5, 7)), verified AS (SELECT s.* FROM base s INNER JOIN remaining_keys k ON s.plan = k.plan), filtered AS (SELECT *, DATEDIFF(CURRENT_DATE(), start_date) / 30 AS months_since_start_date, DATEDIFF(end_date, start_date) AS days_start_date_to_end_date FROM verified WHERE customer_id = 18), enriched AS (SELECT *, DENSE_RANK() OVER (PARTITION BY status ORDER BY monthly_fee) AS monthly_fee_dense_rank, COUNT(months_since_start_date) OVER (PARTITION BY plan, status) AS plan_count_months_since_start_date FROM filtered WHERE customer_id IN (15, 32)), enriched_subscriptions AS (SELECT a.id, a.customer_id, a.start_date, a.end_date, a.monthly_fee, a.status, a.start_date_label, a.months_since_start_date, a.days_start_date_to_end_date, a.monthly_fee_dense_rank, a.plan_count_months_since_start_date, b.credit_limit FROM enriched a INNER JOIN customers b ON a.customer_id = b.id) SELECT *, DENSE_RANK() OVER (ORDER BY days_start_date_to_end_date NULLS FIRST) AS days_start_date_to_end_date_dense_rank, SUM(days_start_date_to_end_date) OVER (PARTITION BY customer_id, status) AS customer_id_sum_days_start_date_to_end_date FROM enriched_subscriptions;
